query.base:
TS metrics-gcp.cloudsql_sqlserver.otel-*
| WHERE gcp.resource_type == "cloudsql_database"
// uptime is a DELTA metric: seconds the instance ran within each 60 s sample.
// Duplicate samples of a series carry the same value at the same timestamp, so take
// MAX per minute: summing would double them and hide a partial start minute.
// up is the instance state at the end of the same sample (1 running, 0 stopped).
| STATS uptime_s = MAX(MAX_OVER_TIME(`cloudsql.googleapis.com/database/uptime`)),
        up = MIN(MIN_OVER_TIME(`cloudsql.googleapis.com/database/up`)),
        ss = SUM(COUNT_OVER_TIME(`cloudsql.googleapis.com/database/sqlserver/memory/page_life_expectancy`))
    BY `@timestamp` = TBUCKET(1 minute), database_id
// SQL Server engine marker over the whole 24h rule window, so an instance in a
// crash loop (or still warming up) stays in scope.
| INLINE STATS ss_total = SUM(ss) BY database_id
// Signal window: restarts seen in the last 30 minutes (>= 15 min for ingest delay).
| WHERE ss_total > 0 AND `@timestamp` >= NOW() - 30 minutes
// A start is a partial minute (0 < uptime < 55 s) that ends with the instance running
// (up == 1). A stop also leaves a partial minute, but it ends with up == 0 and is
// not counted, so a stop/start cycle counts once. Healthy samples read ~60 s.
| EVAL is_restart = CASE(uptime_s > 0 AND uptime_s < 55 AND up == 1, 1, 0),
       restart_ts = CASE(is_restart == 1, `@timestamp`, NULL)
| STATS restarts = SUM(is_restart), last_restart = MAX(restart_ts) BY database_id
